do $$ declare eid uuid; jid uuid; f jsonb; n integer; begin
 for n in 1..4 loop
 eid=('30000000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid;
 jid=('20000000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid;
 if not exists(select 1 from evaluations where id=eid) then
 insert into evaluations(id,code,job_id,job_revision,job_snapshot,framework_id,framework_snapshot,author,created_at)
 select eid,'EV-DEMO-'||n,jid,j.revision,to_jsonb(j),f.id,f.definition,'Demo evaluator',now()-make_interval(days=>n*2) from jobs j cross join frameworks f where j.id=jid and f.code='OPEN-1';
 for f in select value from jsonb_array_elements((select definition->'factors' from frameworks where code='OPEN-1')) loop
 if n<>4 or f->>'code'='skills' then
 insert into scores(evaluation_id,factor,level,rationale,evidence) values(eid,f->>'code',case when n=2 then 3 else 2 end,'Fictional job analysis records the demands of the role.','DEMO interview notes, section '||(f->>'code'));
 end if;end loop;
 if n in(1,3) then update evaluations set status='approved',total=8,grade='E2',reviewer='Demo panel chair',review_note='Demo cross-role calibration completed',bias_evidence='Checked overlooked emotional effort and working conditions',decided_at=now(),submitted_at=now() where id=eid;
 elsif n=2 then update evaluations set status='submitted',submitted_at=now()-interval '5 days' where id=eid;
 end if;
 end if;end loop;end $$;
